Solution: You're computing the magnitude of the vector incorrectly. The formula for the magnitude of a vector is sqrt(x1^2 + x2^2 +... + xn^2), where xi is the ith element of the vector. In your code, you're computing the sum of the squares of each element instead. The correct code would be:

```c
#include <iostream>
#include <vector>
using namespace std;

int main(){
    vector<double> v = {2, 1, 1};
    double norm = 0;

    for(int i = 0; i < v.size(); i++){
        norm += pow(v[i], 2);
    }
    norm = sqrt(norm);

    for(int i = 0; i < v.size(); i++){
        v[i] /= norm;
    }

    for(int i = 0; i < v.size(); i++){
        cout << v[i] << " ";
    }
    cout << endl;

    return 0;
}
```
This will give the correct result of 0.57735 0.28868 0.28868.

